import json,math,statistics
from pathlib import Path
R=Path(__file__).resolve().parents[2]
def wilson(k,n):
 z=1.96;p=k/n;d=1+z*z/n;c=(p+z*z/(2*n))/d;h=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [round(c-h,4),round(c+h,4)]
def score(p,g):
 ids=set(p.get('source_ids',[]));gold=set(g['source_ids']);status=p.get('status','error');exact=status==g['status'] and ids==gold;ga=g['association'];pa=p.get('association');return dict(exact=exact,status_correct=status==g['status'],tp=len(ids&gold),fp=len(ids-gold),fn=len(gold-ids),unsupported_answer=status=='answer' and (g['status']!='answer' or not ids or bool(ids-gold)),missed_answer=g['status']=='answer' and status!='answer',abstention_correct=g['status']!='answer' and status==g['status'],association_correct=pa==ga,complete_workflow=exact and pa==ga,link_tp=int(bool(ga and ga['target_id'] and pa==ga)),link_fp=int(bool(pa and pa['target_id'] and pa!=ga)),link_fn=int(bool(ga and ga['target_id'] and pa!=ga)))
records=[]
